import styled from 'styled-components';
import { useState } from 'react';

export const Blocks = styled.div`
  display: flex;
  justify-content: space-evenly;
  padding: 100px;
  border:1px solid black;
`;

export const Button = styled.button`
width:clamp(100px, 11vw, 200px);
`

export const Btn = styled.button`
width:clamp(50px, 6vw, 100px);
`

export const Btnmain = () => {
  const [disabled, setDisabled] = useState(false);

  const handleClick = () => {
    setDisabled(true);
  };



  return (
    <Blocks className="buttons">
      <Button className="button1" disabled={disabled}>Primery</Button>
      <Button className="button2" disabled={disabled}>Secondary</Button>
      <Button className="button3" disabled={disabled}>Secondary2</Button>
      <Btn onClick={handleClick}>заглушка</Btn>
    </Blocks>
  );
};
